def main():
    existing = get_existing_norms(exclude_slugs={"cv-nouns-professions-city"})
    entries = []
    skipped = 0

    for item in RAW_NOUNS:
        head = item[0]
        norm = norm_vocab(head)
        if norm in existing:
            skipped += 1
            continue

        gender = item[1]
        level = item[2]
        msa = item[3]
        eg = item[4]
        ex_es = item[5]
        ex_ar = item[6]
        domain = item[7] if len(item) > 7 else "work"

        entry = make_noun(head, gender, level, msa, eg, ex_es, ex_ar, domain=domain, rank=7)
        entries.append(entry)
        existing.add(norm)

    print(f"Professions & City: Prepared {len(entries)} new entries (skipped {skipped} existing).")
    emit_bundle("vocab-cv-nouns-professions-city.json", "cv-nouns-professions-city", "المهن والحرف والمرافق الحضرية والبنية التحتية", entries)

if __name__ == "__main__":
    main()
